```js
// --- Collision robustness constants -----------------------------------------
//
// Per-slice displacement cap: each time slice moves the ball at most BALL_R
// pixels, so no obstacle can be jumped in a single slice — the paddle's
// catching window is PADDLE_H = 12px and a brick's expanded box is at least
// BRICK_H + 2*BALL_R = 34px tall, both larger than the cap (tunneling family).

const MAX_SLICE = BALL_R;

// Extra push past the exit point, so the ball is guaranteed outside the brick
// even under floating-point round-off (sticky family).
const PUSH_EPS = 0.01;

// Minimum |hit| on the paddle: a dead-center hit (hit = 0) would zero vx and
// freeze the ball onto a vertical trajectory (dead-angle family).
const MIN_HIT = 0.25;

// Combo multiplier ceiling (score family).
const MAX_COMBO_MULTIPLIER = 5;
```

createState:

```js
export function createState(level = 1) {
  const speed = ballSpeed(level);
  // Launch direction (right + up) at exactly the level speed, so the norm
  // invariant holds from the first frame (velocity family).
  const norm = Math.hypot(0.5, 1);
  return {
    ...
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: (speed * 0.5) / norm, vy: -speed / norm },
    ...
  };
}
```

Wait — (speed*0.5)/norm and -speed/norm: |v| = sqrt((0.5s/n)² + (s/n)²) = s/n × sqrt(1.25) = s ✓.

comboMultiplier:

```js
export function comboMultiplier(combo) {
  return Math.min(1 + combo * 0.5, MAX_COMBO_MULTIPLIER);
}
```

step():

```js
// Advances the ball by a time step `dt` (in seconds) and handles every bounce:
// walls, ceiling, paddle and bricks, in sub-steps no longer than MAX_SLICE so
// no obstacle can be crossed in a single slice (tunneling family). Brick hits
// are resolved here, not in the render loop (debt #2 paid off).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  let remaining = dt;
  while (remaining > 0) {
    const speed = Math.hypot(state.ball.vx, state.ball.vy) || 1;
    const h = Math.min(remaining, MAX_SLICE / speed);
    remaining -= h;

    const prevX = state.ball.x;
    const prevY = state.ball.y;
    state.ball.x += state.ball.vx * h;
    state.ball.y += state.ball.vy * h;

    if (resolveCollisions(state, prevX, prevY)) return true;
  }
  return false;
}
```

resolveCollisions:

```js
// Moves and bounces the ball for a single sub-step; returns true if the ball
// is lost. Order: walls, ceiling, paddle, then bricks.
function resolveCollisions(state, prevX, prevY) {
  const { ball, paddle } = state;
  const r = ball.r;

  // Side walls
  if (ball.x - r < 0) {
    ball.x = r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + r > WIDTH) {
    ball.x = WIDTH - r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - r < 0) {
    ball.y = r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — the per-slice cap guarantees the ball always lands inside the
  // catching window, so it can never slip past the paddle (paddle family).
  if (
    ball.vy > 0 &&
    ball.y + r >= paddle.y &&
    ball.y + r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - r;
    let hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    if (Math.abs(hit) < MIN_HIT) hit = (hit < 0 ? -1 : 1) * MIN_HIT;
    // Direction (0.6·hit, -1), scaled back to exactly the level speed so the
    // norm invariant holds after the bounce (velocity family).
    const levelSpeed = ballSpeed(state.level);
    const nx = levelSpeed * 0.6 * hit;
    const ny = -levelSpeed;
    const norm = Math.hypot(nx, ny);
    ball.vx = (nx / norm) * levelSpeed;
    ball.vy = (ny / norm) * levelSpeed;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks
  const hits = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length > 0) {
    bounceOffBricks(state, hits, prevX, prevY);
    for (const brick of hits) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  // Exit through the bottom: ball lost
  return ball.y - r > HEIGHT;
}
```

bounceOffBricks:

```js
// Flips the ball out of every brick it overlaps. The face struck is the face
// the ball CROSSED during this sub-step (prev -> now): a clean top hit crossed
// the top face, a clean side hit the side face, a diagonal corner hit crossed
// both (corner family). Crossing-based detection beats raw penetration here:
// a ball straddling the seam between two bricks overlaps both by a few pixels
// horizontally, so the smallest penetration is a side even when the ball is
// coming straight down onto their tops. Each axis is flipped at most once per
// pass, so two bricks of the same seam can never annul each other (seam
// family). The ball is then pushed back along the direction it came from far
// enough to clear every brick (sticky family). If no face was crossed (the
// ball was already overlapping at `prev` — should not happen in normal play),
// fall back to the smallest-penetration rule.
function bounceOffBricks(state, hits, prevX, prevY) {
  const ball = state.ball;
  const r = ball.r;

  let flipX = false;
  let flipY = false;
  let crossed = false;

  for (const brick of hits) {
    const crossedTop = prevY + r <= brick.y && ball.y + r > brick.y;
    const crossedBottom = prevY - r >= brick.y + brick.h && ball.y - r < brick.y + brick.h;
    const crossedLeft = prevX + r <= brick.x && ball.x + r > brick.x;
    const crossedRight = prevX - r >= brick.x + brick.w && ball.x - r < brick.x + brick.w;

    if (crossedTop || crossedBottom) { flipY = true; crossed = true; }
    if (crossedLeft || crossedRight) { flipX = true; crossed = true; }
  }

  if (!crossed) {
    // Fallback: smallest penetration decides the axis; equal means a corner.
    let penX = Infinity;
    let penY = Infinity;
    for (const brick of hits) {
      penX = Math.min(penX, Math.min(ball.x + r - brick.x, brick.x + brick.w - (ball.x - r)));
      penY = Math.min(penY, Math.min(ball.y + r - brick.y, brick.y + brick.h - (ball.y - r)));
    }
    if (penX < penY) flipX = true;
    else if (penY < penX) flipY = true;
    else { flipX = true; flipY = true; }
  }

  // Push the ball back along its incoming direction until its center clears
  // every expanded brick box (brick + radius), plus a small epsilon.
  const speed = Math.hypot(ball.vx, ball.vy) || 1;
  const dx = ball.vx / speed;
  const dy = ball.vy / speed;
  let out = 0;
  for (const brick of hits) {
    const x0 = brick.x - r;
    const x1 = brick.x + brick.w + r;
    const y0 = brick.y - r;
    const y1 = brick.y + brick.h + r;
    let t = Infinity;
    if (dx > 0) t = Math.min(t, (ball.x - x0) / dx);
    else if (dx < 0) t = Math.min(t, (x1 - ball.x) / -dx);
    if (dy > 0) t = Math.min(t, (ball.y - y0) / dy);
    else if (dy < 0) t = Math.min(t, (y1 - ball.y) / -dy);
    out = Math.max(out, t);
  }
  ball.x -= dx * (out + PUSH_EPS);
  ball.y -= dy * (out + PUSH_EPS);

  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  // Norm invariant: after any bounce the speed is exactly the level speed.
  const levelSpeed = ballSpeed(state.level);
  const norm = Math.hypot(ball.vx, ball.vy) || 1;
  ball.vx = (ball.vx / norm) * levelSpeed;
  ball.vy = (ball.vy / norm) * levelSpeed;
}
```

