// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// Brick collision, bounce and scoring live in the pure-logic `step()`, so they
// run anywhere (Node tests included); `frame()` only draws. The module runs
// nothing on import: only `boot()` touches the DOM. Pure logic can therefore
// be imported from the tests (`node --test`) without a browser.

const STORAGE_KEY = 'neon.best';

// --- Collision robustness constants ------------------------------------------
//
// MAX_SLICE caps how far the ball can travel within a single collision pass.
// It is smaller than the paddle's catching window (PADDLE_H = 12px) and far
// below a brick's expanded box (BRICK_H + 2·BALL_R = 34px), so no obstacle can
// ever be jumped in one slice: a ball that crosses an obstacle boundary always
// lands inside it and is caught (traversal family).
const MAX_SLICE = BALL_R;

// Extra distance past the exact exit point, so the ball is guaranteed outside
// the brick even under floating-point round-off (sticky family).
const PUSH_EPS = 0.01;

// Minimum |hit| on the paddle. A dead-center hit (hit = 0) would zero vx and
// freeze the ball on a pure vertical trajectory (dead-angle family).
const MIN_HIT = 0.25;

// Combo multiplier ceiling: a long streak must not blow the score up forever
// (score family).
const MAX_COMBO_MULTIPLIER = 5;

// Launch direction (right + up), scaled to exactly the level speed so the
// norm invariant holds from the first frame (velocity family).
ball: {
  x: WIDTH / 2,
  y: PADDLE_Y - BALL_R - 2,
  r: BALL_R,
  vx: (speed * 0.5) / Math.hypot(0.5, 1),
  vy: -speed / Math.hypot(0.5, 1),
},

