// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

edits.newText:
// --- Physics (movement + every bounce, sub-stepped) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles every bounce:
// walls, ceiling, paddle and bricks. The step is cut into slices of at most
// MAX_SLICE pixels so no obstacle can be crossed between two collision checks
// (traversal family); a lost ball is reported as soon as it exits the bottom.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  let remaining = dt;
  while (remaining > 0) {
    const speed = Math.hypot(state.ball.vx, state.ball.vy) || 1;
    const h = Math.min(remaining, MAX_SLICE / speed);
    remaining -= h;

    const prevX = state.ball.x;
    const prevY = state.ball.y;
    state.ball.x += state.ball.vx * h;
    state.ball.y += state.ball.vy * h;

    if (resolveCollisions(state, prevX, prevY)) return true;
  }
  return false;
}

// Moves and bounces the ball for one sub-step. `prevX`/`prevY` are the
// position at the start of the slice, used to recover the face the ball
// crossed. Returns `true` when the ball is lost through the bottom.
function resolveCollisions(state, prevX, prevY) {
  const { ball, paddle } = state;
  const r = ball.r;

  // Side walls
  if (ball.x - r < 0) {
    ball.x = r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + r > WIDTH) {
    ball.x = WIDTH - r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - r < 0) {
    ball.y = r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle. Because no slice moves the ball more than MAX_SLICE < PADDLE_H, a
  // descending ball always lands inside the catching window: it can never slip
  // past the paddle, even at maximum dt (paddle family).
  if (
    ball.vy > 0 &&
    ball.y + r >= paddle.y &&
    ball.y + r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - r;
    // Rebound angle from where the paddle was hit, with a dead-center guard.
    let hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    if (Math.abs(hit) < MIN_HIT) hit = (hit < 0 ? -1 : 1) * MIN_HIT;
    // Direction (0.6·hit, -1) scaled to exactly the level speed, so the norm
    // invariant holds after the bounce (velocity family).
    const levelSpeed = ballSpeed(state.level);
    const nx = levelSpeed * 0.6 * hit;
    const ny = -levelSpeed;
    const norm = Math.hypot(nx, ny);
    ball.vx = (nx / norm) * levelSpeed;
    ball.vy = (ny / norm) * levelSpeed;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: bounce first, then destroy and score every overlapped brick
  // (the alive gate keeps each brick counted exactly once).
  const hits = state.bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length > 0) {
    bounceOffBricks(state, hits, prevX, prevY);
    for (const brick of hits) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  // Exit through the bottom: ball lost
  return ball.y - r > HEIGHT;
}

// Flips the ball out of every brick it overlaps. The struck face is the face
// the ball CROSSED during this slice: a clean top hit crossed the top face, a
// clean side hit the side face, a diagonal corner hit crossed both (corner
// family). Crossing beats raw penetration here: a ball straddling the seam
// between two bricks overlaps each by a few pixels horizontally, so the
// smallest penetration would read a "side hit" even when the ball comes
// straight down onto their tops. Each axis is flipped at most once per pass,
// so two bricks of the same seam can never annul each other (seam family).
// The ball is then pushed back along its incoming direction far enough to
// clear every brick, guaranteeing it starts the next slice outside (sticky
// family). If no face was crossed (the ball was already overlapping at the
// start of the slice — should not happen in normal play), we fall back to the
// smallest-penetration rule, ties counting as a corner.
function bounceOffBricks(state, hits, prevX, prevY) {
  const ball = state.ball;
  const r = ball.r;

  let flipX = false;
  let flipY = false;
  let crossed = false;

  for (const brick of hits) {
    const crossedTop = prevY + r <= brick.y && ball.y + r > brick.y;
    const crossedBottom = prevY - r >= brick.y + brick.h && ball.y - r < brick.y + brick.h;
    const crossedLeft = prevX + r <= brick.x && ball.x + r > brick.x;
    const crossedRight = prevX - r >= brick.x + brick.w && ball.x - r < brick.x + brick.w;
    if (crossedTop || crossedBottom) {
      flipY = true;
      crossed = true;
    }
    if (crossedLeft || crossedRight) {
      flipX = true;
      crossed = true;
    }
  }

  if (!crossed) {
    // Defensive fallback: the decisive brick is the one with the smallest
    // penetration; its struck axis is the smaller of its two penetrations,
    // ties counting as a corner (both components flip).
    let best = Infinity;
    for (const brick of hits) {
      const penX = Math.min(ball.x + r - brick.x, brick.x + brick.w - (ball.x - r));
      const penY = Math.min(ball.y + r - brick.y, brick.y + brick.h - (ball.y - r));
      const depth = Math.min(penX, penY);
      if (depth < best) {
        best = depth;
        flipX = penX < penY;
        flipY = penY < penX;
      }
    }
    if (!flipX && !flipY) {
      flipX = true;
      flipY = true; // exact corner: penetrations are equal
    }
  }

  // Push the ball back along its incoming direction until its center clears
  // every expanded brick box (brick inflated by the radius), plus PUSH_EPS.
  const speed = Math.hypot(ball.vx, ball.vy) || 1;
  const dx = ball.vx / speed;
  const dy = ball.vy / speed;
  let out = 0;
  for (const brick of hits) {
    const x0 = brick.x - r;
    const x1 = brick.x + brick.w + r;
    const y0 = brick.y - r;
    const y1 = brick.y + brick.h + r;
    let t = Infinity;
    if (dx > 0) t = Math.min(t, (ball.x - x0) / dx);
    else if (dx < 0) t = Math.min(t, (x1 - ball.x) / -dx);
    if (dy > 0) t = Math.min(t, (ball.y - y0) / dy);
    else if (dy < 0) t = Math.min(t, (y1 - ball.y) / -dy);
    out = Math.max(out, t);
  }
  ball.x -= dx * (out + PUSH_EPS);
  ball.y -= dy * (out + PUSH_EPS);

  // Flip the struck axis(es) — at most once per axis per pass.
  if (flipX) ball.vx = -ball.vx;
  if (flipY) ball.vy = -ball.vy;

  // Norm invariant: after any bounce the speed is exactly the level speed.
  const levelSpeed = ballSpeed(state.level);
  const norm = Math.hypot(ball.vx, ball.vy) || 1;
  ball.vx = (ball.vx / norm) * levelSpeed;
  ball.vy = (ball.vy / norm) * levelSpeed;
}

