import { createState, step, collides, ballSpeed } from './game/neon.js';
let seed = 42;
const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
for (let level = 1; level <= 10; level++) {
  const state = createState(level);
  let frames = 0, bounces = 0;
  while (frames < 20000 && state.bricks.some(b => b.alive)) {
    const dt = 0.005 + rnd() * 0.045;            // 30..144fps equivalent, incl. max dt
    if (level % 2 === 0) state.paddle.x = Math.floor(rnd() * (640 - 96)); // paddle teleports
    const lost = step(state, dt);
    frames++;
    if (lost) { state.ball = createState(level).ball; continue; }
    // invariants
    const v = Math.hypot(state.ball.vx, state.ball.vy);
    if (Math.abs(v - ballSpeed(level)) > 1e-6) throw new Error('bad speed lvl ' + level + ': ' + v);
    for (const b of state.bricks) if (b.alive && collides(state.ball, b)) {
      throw new Error('ball inside brick lvl ' + level);
    }
    if (Math.abs(state.ball.vx) < 0.001 && Math.abs(state.ball.vy) < 0.001) throw new Error('ball stuck');
    bounces += Math.abs(state.ball.vx) + Math.abs(state.ball.vy) > 0 ? 1 : 0;
  }
  console.log('level', level, 'ok — frames', frames, 'ball', state.ball.x.toFixed(1), state.ball.y.toFixed(1));
}
console.log('ALL LEVELS OK');
"

